  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition)
  }

  /** helper function to set the values of all input ports.
   * @param decision_frame payload for data port decision_frame
   */
  def put_concrete_inputs(decision_frame : EIT_Acquisition_Supervisor.DecisionFrame): Unit = {
    put_decision_frame(decision_frame)
  }


  /** helper function to check PublicationComposition_acquisition_process_publication_composition's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param control_frame method that will be called with the value of the outgoing data
   *        port 'control_frame'.
   * @param status_frame method that will be called with the value of the outgoing data
   *        port 'status_frame'.
   */
  def check_concrete_output(control_frame: EIT_Acquisition_Supervisor.ControlFrame => B,
                            status_frame: EIT_Acquisition_Supervisor.StatusFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val control_frameValue: EIT_Acquisition_Supervisor.ControlFrame = get_control_frame().get
    if(!control_frame(control_frameValue)) {
      testFailures = testFailures :+ st"'control_frame' did not match expected: value of the outgoing data port is ${control_frameValue}"
    }
    val status_frameValue: EIT_Acquisition_Supervisor.StatusFrame = get_status_frame().get
    if(!status_frame(status_frameValue)) {
      testFailures = testFailures :+ st"'status_frame' did not match expected: value of the outgoing data port is ${status_frameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_decision_frame(value : EIT_Acquisition_Supervisor.DecisionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.operational_api.decision_frame_Id, EIT_Acquisition_Supervisor.DecisionFrame_Payload(value))
  }

  // getter for out DataPort
  def get_control_frame(): Option[EIT_Acquisition_Supervisor.ControlFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.ControlFrame] = get_control_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.ControlFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port control_frame.  Expecting 'EIT_Acquisition_Supervisor.ControlFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.ControlFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_control_frame_payload(): Option[EIT_Acquisition_Supervisor.ControlFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.initialization_api.control_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.ControlFrame_Payload]]
  }

  // getter for out DataPort
  def get_status_frame(): Option[EIT_Acquisition_Supervisor.StatusFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.StatusFrame] = get_status_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.StatusFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port status_frame.  Expecting 'EIT_Acquisition_Supervisor.StatusFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.StatusFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_status_frame_payload(): Option[EIT_Acquisition_Supervisor.StatusFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.initialization_api.status_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.StatusFrame_Payload]]
  }

